/**
 * Katalog tema non-pernikahan: Ulang Tahun, Syukuran, Acara Lain, dan Ucapan.
 * Sama seperti themesCatalog.js: "keluarga" menentukan gaya dasar, tiap baris mengatur palet,
 * teks bawaan (sesuai jenis acaranya), dan bagian yang berbeda.
 */

const vars = (radius, btn, shadow, spacing = '0', transform = 'none') => ({
  '--radius': radius,
  '--btn-radius': btn,
  '--btn-shadow': shadow,
  '--heading-spacing': spacing,
  '--heading-transform': transform,
});
const c = (primary, secondary, background, surface, text) => ({ primary, secondary, background, surface, text });
const fx = (shapes, count, motion, size, glow = ['primary', 'secondary'], patternMotion = 'none') => ({ particles: { shapes, count, motion, size }, patternMotion, glow });
const ev = (id, title, time, place = 'Kediaman Keluarga', date = '2026-12-12') => ({ id, title, date, time, place });
const P = (name, fullName, parents = '') => ({ name, fullName, parents });
const SALAM = 'Assalamu’alaikum Warahmatullahi Wabarakatuh';

/* ── Penyusun teks ───────────────────────────────────────────── */
function invitation({ label, names, openingTitle, opening, profileTitle, people, events, gallery, rsvp, gift, quote, source = '', message, signature }) {
  return {
    cover: { label, names },
    opening: { title: openingTitle, text: opening },
    profile: { title: profileTitle, people },
    events,
    gallery: gallery ?? { title: 'Galeri', caption: '' },
    rsvp: rsvp ?? { title: 'Konfirmasi Kehadiran', text: 'Mohon kabari kehadiran Anda agar kami dapat mempersiapkan acara dengan baik.' },
    gift: gift ?? { title: 'Tanda Kasih', text: 'Doa dan kehadiran Anda adalah hadiah terbaik. Bila ingin memberi tanda kasih, dapat melalui:' },
    closing: { quote, source, message, signature },
  };
}

function greeting({ label, names, title, text, profileTitle = 'Untukmu', person, gallery, quote, source = '', message, signature, guestText = 'Ada pesan spesial untukmu', buttonText = 'Buka Ucapan' }) {
  return {
    cover: { label, names, guestText, buttonText },
    opening: { title, text },
    profile: { title: profileTitle, people: [person ?? P(names, names, '')] },
    gallery: gallery ?? { title: 'Kenangan', caption: '' },
    closing: { quote, source, message, signature },
  };
}

const kid = ({ name = 'Alya', age = 5, boy = false, hook = 'pesta ulang tahun', gallery = 'Momen Ceria', time = '15.00 – 17.00 WIB', place = 'Kediaman Keluarga' } = {}) =>
  invitation({
    label: `ULANG TAHUN KE-${age}`,
    names: name,
    openingTitle: 'Halo, Teman-Teman!',
    opening: `Yuk datang ke ${hook} ${name}! Ada kue, permainan seru, dan banyak kejutan. Ajak juga Ayah dan Bunda, ya!`,
    profileTitle: 'Yang Berulang Tahun',
    people: [P(name, `${name} ${boy ? 'Pratama' : 'Putri Pratama'}`, `${boy ? 'Putra' : 'Putri'} dari Bapak Hendra & Ibu Sari`)],
    events: [ev('ev-party', 'Pesta Ulang Tahun', time, place)],
    gallery: { title: gallery, caption: 'Tumbuh besar dengan senyum dan tawa.' },
    rsvp: { title: 'Kamu Datang, Kan?', text: 'Kabari kami ya, supaya kue dan bingkisannya cukup untuk semua.' },
    gift: { title: `Kado untuk ${name}`, text: 'Kehadiranmu sudah jadi kado terindah. Jika ingin berbagi hadiah:' },
    quote: `“Semoga ${name} tumbuh sehat, ceria, dan menjadi kebanggaan keluarga.”`,
    message: 'Terima kasih sudah datang dan ikut merayakan!',
    signature: `${name} & Keluarga`,
  });

const teen = ({ name = 'Nadia', age = 17, label, hook = 'merayakan hari spesialku', dress = '', time = '19.00 – 22.00 WIB', place = 'The Glasshouse' } = {}) =>
  invitation({
    label: label ?? `${age}TH BIRTHDAY`,
    names: name,
    openingTitle: 'You’re Invited!',
    opening: `Aku mengundangmu ${hook}. ${dress ? `Dress code: ${dress}. ` : ''}Datang, bawa senyum terbaikmu, dan mari bikin malam ini tak terlupakan.`,
    profileTitle: 'The Birthday Star',
    people: [P(name, `${name} Larasati`, `Merayakan usia ke-${age}`)],
    events: [ev('ev-party', 'Birthday Party', time, place)],
    gallery: { title: 'Throwback', caption: 'Bab-bab kecil menuju hari ini.' },
    rsvp: { title: 'RSVP', text: 'Konfirmasi kehadiranmu, ya. Tempatnya terbatas!' },
    gift: { title: 'Birthday Gift', text: 'Kehadiranmu sudah lebih dari cukup. Tapi kalau ingin kirim hadiah:' },
    quote: '“Here’s to new adventures, bigger dreams, and better days.”',
    message: 'Can’t wait to celebrate with you!',
    signature: name,
  });

const milestone = ({ name = 'Bapak Hendra', short = 'Hendra', age = 50, label, opening, time = '18.30 – 21.00 WIB', place = 'Ballroom Hotel Santika', signature = 'Keluarga Besar' } = {}) =>
  invitation({
    label: label ?? `${age} TAHUN`,
    names: name,
    openingTitle: 'Dengan Penuh Syukur',
    opening: opening ?? `Atas berkat dan rahmat Tuhan, kami mengundang Bapak/Ibu/Saudara/i untuk merayakan ${age} tahun perjalanan hidup ${name}.`,
    profileTitle: 'Yang Berbahagia',
    people: [P(short, name, `Merayakan ${age} tahun usia`)],
    events: [ev('ev-dinner', 'Makan Malam Perayaan', time, place)],
    gallery: { title: `${age} Tahun Kenangan`, caption: 'Perjalanan panjang yang penuh syukur.' },
    quote: '“Usia bukan tentang berapa lama kita hidup, tetapi seberapa banyak cinta yang kita bagikan.”',
    message: 'Kehadiran dan doa Anda akan melengkapi kebahagiaan kami.',
    signature,
  });

/** Syukuran / acara keluarga. */
const tasyakuran = ({ label, names, islami = true, openingTitle, opening, profileTitle = 'Tuan Rumah', people, event, time = '10.00 – 13.00 WIB', place = 'Kediaman Keluarga', gallery, quote, source = '', message, signature = 'Keluarga Bapak Hendra' }) =>
  invitation({
    label,
    names,
    openingTitle: openingTitle ?? (islami ? SALAM : 'Salam Sejahtera'),
    opening,
    profileTitle,
    people: people ?? [P('Keluarga Hendra', 'Keluarga Bapak Hendra & Ibu Sari', 'Tuan rumah acara')],
    events: [ev('ev-main', event, time, place)],
    gallery: gallery ?? { title: 'Galeri', caption: 'Momen syukur bersama keluarga.' },
    quote,
    source,
    message: message ?? (islami ? 'Jazakumullah khairan atas doa dan kehadiran Bapak/Ibu/Saudara/i.' : 'Terima kasih atas doa dan kehadiran Bapak/Ibu/Saudara/i.'),
    signature,
  });

/** Acara umum (kantor, komunitas, sekolah, hari raya). */
const eventCopy = ({ label, names, openingTitle = 'Anda Diundang', opening, profileTitle = 'Penyelenggara', people, events, gallery, rsvp, gift, quote, source = '', message = 'Sampai jumpa di acara!', signature = 'Panitia' }) =>
  invitation({
    label,
    names,
    openingTitle,
    opening,
    profileTitle,
    people: people ?? [P('Panitia', 'Panitia Penyelenggara', 'Hubungi kami untuk informasi lebih lanjut')],
    events,
    gallery: gallery ?? { title: 'Dokumentasi', caption: '' },
    rsvp: rsvp ?? { title: 'Registrasi', text: 'Konfirmasi kehadiran Anda agar kami dapat menyiapkan tempat.' },
    gift: gift ?? { title: 'Dukungan', text: 'Bila ingin berpartisipasi atau berdonasi, dapat melalui:' },
    quote,
    source,
    message,
    signature,
  });

